// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 1, 1e24);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);
        assertEq(address(c).balance, amount);
        uint256 ownerBefore = address(this).balance;
        c.withdrawAll();
        assertTrue(address(this).balance == ownerBefore + amount);
    }
}
